hooks.command:
python3 -c "
import json, sys
data = json.load(sys.stdin)
path = data.get('tool_input', {}).get('path', '') or data.get('tool_input', {}).get('file_path', '')
if not path:
    sys.exit(0)
try:
    content = open(path).read()
except Exception:
    sys.exit(0)
warnings = []
if 'console.log' in content and path.endswith(('.js', '.ts', '.jsx', '.tsx')):
    warnings.append('console.log')
if 'import pdb' in content or 'pdb.set_trace' in content:
    warnings.append('pdb breakpoint')
if warnings:
    print(f'[Hook] Debug artifacts found in {path}: {", ".join(warnings)} — remove before committing', file=sys.stderr)
sys.exit(0)
"
